.mn-kpi-card {
  display: grid;
  gap: var(--space-1, 4px);
  padding: var(--space-3, 12px) var(--space-4, 16px);
  background: var(--color-light-surface, #ffffff);
  border: var(--web-stroke-line, 1px) solid var(--web-color-separator, #b4bcc8);
  border-radius: var(--radius-card, 4px);
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
}
.mn-kpi-card__label {
  font-size: var(--web-text-caption, 12px);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-light-text-muted, #6b7280);
  /* Deutsche Komposita in schmalen Karten: nach Silben trennen (Seite traegt lang="de"),
     als letzte Stufe umbrechen statt aus der Karte laufen. */
  -webkit-hyphens: auto;
  hyphens: auto;
  overflow-wrap: break-word;
}
.mn-kpi-card__value {
  font-size: var(--web-text-h3, 23px);
  line-height: var(--web-leading-h3, 1.3);
  font-weight: 700;
  color: var(--color-light-h1, #312e81);
}
.mn-kpi-card__change {
  font-size: var(--web-text-caption, 12px);
  font-weight: 600;
}
.mn-kpi-card__change.is-up {
  color: var(--color-status-success, #2e7d32);
}
.mn-kpi-card__change.is-down {
  color: var(--color-status-error, #d32f2f);
}
.mn-kpi-card__change.is-neutral {
  color: var(--color-light-text-muted, #6b7280);
}
.mn-kpi-card__change.is-gut {
  color: var(--color-status-success, #2e7d32);
}
.mn-kpi-card__change.is-schlecht {
  color: var(--color-status-error, #d32f2f);
}
.mn-kpi-card__change.is-ungewertet {
  color: var(--color-light-text-muted, #6b7280);
}
.mn-kpi-card__sparkline {
  margin: var(--space-1, 4px) 0;
  line-height: 0;
}
.mn-kpi-card__caption {
  font-size: var(--web-text-caption, 12px);
  font-style: italic;
  color: var(--color-light-text-muted, #6b7280);
}

page_header_css:
.mn-page-header {
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
  margin-bottom: var(--space-6, 24px);
}
.mn-page-header__title {
  font-size: var(--web-text-h1, 33px);
  line-height: var(--web-leading-h1, 1.18);
  font-weight: 700;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--color-light-h1, #312e81);
}
.mn-page-header__lead {
  font-size: var(--web-text-lead, 19px);
  line-height: var(--web-leading-lead, 1.55);
  margin: var(--space-2, 8px) 0 0;
  color: var(--color-light-text-muted, #6b7280);
}

footer_css:
.mn-footer {
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
  margin-top: var(--space-8, 32px);
  padding-top: var(--space-4, 16px);
  border-top: var(--web-stroke-line, 1px) solid var(--web-color-separator, #b4bcc8);
}
.mn-footer__inner {
  max-width: var(--web-layout-content-width, 1024px);
  margin-inline: auto;
  padding-inline: var(--web-layout-page-inset, 44px);
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--space-2, 8px) var(--space-6, 24px);
  font-size: var(--web-text-ui, 14px);
  line-height: var(--web-leading-ui, 1.35);
  color: var(--color-light-text-muted, #6b7280);
}
.mn-footer__identity,
.mn-footer__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
}
.mn-footer__sep {
  margin: 0 var(--space-2, 8px);
  opacity: 0.5;
}
.mn-footer__link {
  color: var(--color-light-text-muted, #6b7280);
  text-decoration: none;
}
.mn-footer__link:hover {
  text-decoration: underline;
}
.mn-footer__link:focus-visible {
  outline: var(--web-stroke-focus, 2px) solid var(--web-color-focus-ring, #4F46E5);
  outline-offset: 2px;
}
.mn-footer__version {
  color: var(--color-light-text-subtle, #9ca3af);
}

tier_chip_css:
.mn-tier-chip {
  display: inline-block;
  padding: var(--space-1, 4px) var(--space-2, 8px);
  border-radius: var(--radius-subtle, 2px);
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
  font-size: var(--web-text-caption, 12px);
  line-height: var(--web-leading-caption, 1.4);
  font-weight: 600;
  cursor: default;
}
.mn-tier-chip--bordered {
  border: var(--web-stroke-line, 1px) solid transparent;
}
.mn-tier-chip--loading {
  background: var(--color-light-surface-subtle, #f6f6f6);
  color: var(--color-light-text-muted, #6b7280);
  font-style: italic;
}
.mn-tier-chip--bibliothek {
  background: var(--color-tier-bibliothek-bg, #f0fdf4);
  color: var(--color-tier-bibliothek-text, #166534);
}
.mn-tier-chip--bibliothek.mn-tier-chip--bordered {
  border-color: var(--color-tier-bibliothek-border, #bbf7d0);
}
.mn-tier-chip--atelier {
  background: var(--color-tier-atelier-bg, #fffbeb);
  color: var(--color-tier-atelier-text, #92400e);
}
.mn-tier-chip--atelier.mn-tier-chip--bordered {
  border-color: var(--color-tier-atelier-border, #fde68a);
}
.mn-tier-chip--kabinett {
  background: var(--color-tier-kabinett-bg, #fef2f2);
  color: var(--color-tier-kabinett-text, #991b1b);
}
.mn-tier-chip--kabinett.mn-tier-chip--bordered {
  border-color: var(--color-tier-kabinett-border, #fecaca);
}
.mn-tier-chip--start {
  background: var(--color-tier-start-bg, #f0fdf4);
  color: var(--color-tier-start-text, #166534);
}
.mn-tier-chip--start.mn-tier-chip--bordered {
  border-color: var(--color-tier-start-border, #bbf7d0);
}
.mn-tier-chip--observatorium {
  background: var(--color-tier-observatorium-bg, #fffbeb);
  color: var(--color-tier-observatorium-text, #92400e);
}
.mn-tier-chip--observatorium.mn-tier-chip--bordered {
  border-color: var(--color-tier-observatorium-border, #fde68a);
}
.mn-tier-chip--magazin {
  background: var(--color-tier-magazin-bg, #f5f5f5);
  color: var(--color-tier-magazin-text, #374151);
}
.mn-tier-chip--magazin.mn-tier-chip--bordered {
  border-color: var(--color-tier-magazin-border, #e5e7eb);
}
.mn-tier-chip--archiv {
  background: var(--color-tier-archiv-bg, #f5f5f5);
  color: var(--color-tier-archiv-text, #374151);
}
.mn-tier-chip--archiv.mn-tier-chip--bordered {
  border-color: var(--color-tier-archiv-border, #e5e7eb);
}

card_grid_css:
.mn-card-grid {
  display: grid;
  grid-template-columns: repeat(var(--mn-card-grid-cols, 3), 1fr);
  gap: var(--space-4, 16px);
}
@media (max-width: 1023.98px) {
  .mn-card-grid {
    grid-template-columns: repeat(var(--mn-card-grid-cols-tablet, var(--mn-card-grid-cols, 3)), 1fr);
  }
}
@media (max-width: 639.98px) {
  .mn-card-grid {
    grid-template-columns: 1fr;
  }
}

datei_zeile_css:
.mn-datei-liste {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: var(--web-stroke-line, 1px) solid var(--color-light-border, #cbd5e1);
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
}
.mn-datei-zeile {
  position: relative;
  display: grid;
  grid-template-columns: var(--web-touch-target, 44px) minmax(0, 1fr) auto auto var(--web-touch-target, 44px);
  grid-template-areas: "k n m g a" "k s m g a";
  column-gap: var(--space-4, 16px);
  align-items: center;
  min-height: var(--web-touch-target, 44px);
  padding: var(--space-2, 8px) 0;
  border-bottom: var(--web-stroke-line, 1px) solid var(--color-light-border, #cbd5e1);
}
.mn-datei-zeile__kennung,
.mn-datei-zeile__vorschau {
  grid-area: k;
  align-self: center;
}
.mn-datei-zeile__kennung {
  display: inline-block;
  justify-self: start;
  white-space: nowrap;
  font-size: var(--web-text-caption, 12px);
  line-height: var(--web-leading-caption, 1.4);
  font-weight: var(--font-weight-medium, 500);
  letter-spacing: var(--font-tracking-wide, 0.04em);
  text-transform: uppercase;
  color: var(--color-light-text-muted, #6b7280);
  border: var(--web-stroke-line, 1px) solid var(--color-light-border, #cbd5e1);
  border-radius: var(--radius-subtle, 2px);
  padding: 0 var(--space-1, 4px);
}
.mn-datei-zeile__vorschau {
  width: var(--space-10, 40px);
  height: var(--space-10, 40px);
  object-fit: cover;
  border-radius: var(--radius-subtle, 2px);
  background: var(--color-light-surface-subtle, #f6f6f6);
}
.mn-datei-zeile__name {
  grid-area: n;
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: var(--web-text-body, 16px);
  line-height: var(--web-leading-ui, 1.35);
  color: var(--color-light-text, #1e1b4b);
  text-decoration: none;
}
.mn-datei-zeile--ordner .mn-datei-zeile__name {
  font-weight: var(--font-weight-medium, 500);
}
.mn-datei-zeile--ordner .mn-datei-zeile__name::after {
  content: "";
  position: absolute;
  inset: 0;
}
.mn-datei-zeile__name:hover {
  color: var(--color-light-accent, #4F46E5);
  text-decoration: underline;
}
.mn-datei-zeile__name:focus-visible,
.mn-datei-zeile__aktion:focus-visible {
  outline: var(--web-stroke-focus, 2px) solid var(--web-color-focus-ring, #4F46E5);
  outline-offset: var(--space-1, 4px);
}
.mn-datei-zeile__satz {
  grid-area: s;
  font-size: var(--web-text-ui, 14px);
  line-height: var(--web-leading-ui, 1.35);
  color: var(--color-light-text-muted, #6b7280);
}
.mn-datei-zeile__etikett {
  font-size: var(--web-text-caption, 12px);
  font-weight: var(--font-weight-medium, 500);
  letter-spacing: var(--font-tracking-wide, 0.04em);
  text-transform: uppercase;
}
.mn-datei-zeile__meta {
  grid-area: m;
  text-align: right;
  font-size: var(--web-text-ui, 14px);
  line-height: var(--web-leading-ui, 1.35);
  color: var(--color-light-text-muted, #6b7280);
  font-variant-numeric: tabular-nums;
}
.mn-datei-zeile__meta--groesse {
  grid-area: g;
}
.mn-datei-zeile__neu {
  grid-area: n;
  justify-self: end;
  font-size: var(--web-text-caption, 12px);
  font-weight: var(--font-weight-medium, 500);
  letter-spacing: var(--font-tracking-wide, 0.04em);
  text-transform: uppercase;
  color: var(--color-light-accent, #4F46E5);
}
.mn-datei-zeile__aktion {
  grid-area: a;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--web-touch-target, 44px);
  height: var(--web-touch-target, 44px);
  padding: 0;
  border: 0;
  background: transparent;
  font: inherit;
  color: var(--color-light-text-muted, #6b7280);
  position: relative;
}
button.mn-datei-zeile__aktion {
  cursor: pointer;
}
button.mn-datei-zeile__aktion:hover {
  background: var(--color-light-surface-subtle, #f6f6f6);
}
@media (max-width: 640px) {
  .mn-datei-zeile {
    grid-template-columns: var(--web-touch-target, 44px) minmax(0, 1fr) var(--web-touch-target, 44px);
    grid-template-areas: "k n a" "k s a" "k m a";
    column-gap: var(--space-3, 12px);
  }
  .mn-datei-zeile__meta {
    text-align: left;
  }
  .mn-datei-zeile__meta--groesse {
    display: none;
  }
}

empty_state_css:
.mn-empty-state {
  padding: var(--space-6, 24px) var(--space-5, 20px);
  border-radius: var(--radius-subtle, 2px);
  background: var(--color-light-surface-subtle, #f6f6f6);
  border-left: var(--web-stroke-line-strong, 2px) solid var(--web-color-separator, #b4bcc8);
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
}
.mn-empty-state__message {
  margin: 0;
  font-size: var(--web-text-ui, 14px);
  line-height: var(--web-leading-ui, 1.35);
  color: var(--color-light-text-muted, #6b7280);
}
.mn-empty-state--bibliothek {
  border-left-color: var(--color-tier-bibliothek-border, #cbd5e1);
}
.mn-empty-state--atelier {
  border-left-color: var(--color-tier-atelier-border, #cbd5e1);
}
.mn-empty-state--kabinett {
  border-left-color: var(--color-tier-kabinett-border, #cbd5e1);
}
.mn-empty-state--start {
  border-left-color: var(--color-tier-start-border, #cbd5e1);
}
.mn-empty-state--observatorium {
  border-left-color: var(--color-tier-observatorium-border, #cbd5e1);
}
.mn-empty-state--magazin {
  border-left-color: var(--color-tier-magazin-border, #cbd5e1);
}
.mn-empty-state--archiv {
  border-left-color: var(--color-tier-archiv-border, #cbd5e1);
}

zeitraum_leiste_css:
.mn-zeitraum-leiste {
  display: inline-flex;
  max-width: 100%;
  background: var(--color-light-surface, #ffffff);
  border: var(--web-stroke-line, 1px) solid var(--web-color-separator, #b4bcc8);
  border-radius: var(--radius-subtle, 2px);
  overflow: hidden;
  font-family: var(--web-font-sans, "Geist"), system-ui, sans-serif;
}
.mn-zeitraum-leiste__option {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--web-touch-target, 44px);
  min-width: var(--web-touch-target, 44px);
  padding: 0 var(--space-4, 16px);
  font-size: var(--web-text-ui, 14px);
  line-height: var(--web-leading-ui, 1.35);
  font-weight: 500;
  white-space: nowrap;
  text-decoration: none;
  color: var(--color-light-text-muted, #6b7280);
  border-right: var(--web-stroke-line, 1px) solid var(--web-color-separator, #b4bcc8);
}
.mn-zeitraum-leiste__option:last-child {
  border-right: 0;
}
.mn-zeitraum-leiste__option:hover {
  background: var(--color-light-surface-subtle, #f6f6f6);
  color: var(--color-light-text, #1e1b4b);
}
.mn-zeitraum-leiste__option[aria-current="page"] {
  background: var(--color-indigo-50, #eef2ff);
  color: var(--color-light-accent, #4F46E5);
}
.mn-zeitraum-leiste__option:focus-visible {
  outline: var(--web-stroke-focus, 2px) solid var(--web-color-focus-ring, #4F46E5);
  outline-offset: calc(var(--web-stroke-focus, 2px) * -1);
}
